// Turns one normalised lead (from "Normalise and score" in the lead intake workflow)
// into HubSpot request bodies. Field map: docs/HUBSPOT_PLAN.md.
const PIPELINE_ID = '2630364862'; // TCA new business
const STAGE_NEW_LEAD = '4456833770';
const SERVICE_LABELS = {
  brand: 'Brand and identity',
  website: 'Website design and build',
  marketing: 'Marketing and ads',
  seo: 'SEO and content',
  social: 'Social media',
  unsure: 'Not sure yet',
};

const l = $input.first().json;
const email = String(l.email ?? '').trim().toLowerCase();
const leadId = String(l.id ?? '').trim();
if (!email) throw new Error('Lead has no email, nothing to sync');
if (!leadId) throw new Error('Lead has no id, cannot upsert the deal');

// Only send values the visitor gave: an empty string would wipe what HubSpot already holds.
const put = (o, key, value) => {
  if (value === undefined || value === null) return;
  const s = String(value).trim();
  if (s !== '') o[key] = s;
};

const [first, ...rest] = String(l.name ?? '').trim().split(/\s+/);
const services = String(l.services ?? '').split(',').map((s) => s.trim()).filter(Boolean);
const receivedMs = Date.parse(l.receivedAtUtc);

const contact = { email };
put(contact, 'firstname', first);
put(contact, 'lastname', rest.join(' '));
put(contact, 'phone', l.phone);
put(contact, 'company', l.company);
put(contact, 'website', l.website);
put(contact, 'tca_lead_id', leadId);
put(contact, 'tca_source', l.source);
put(contact, 'tca_services', services.join(';')); // multiple checkboxes: semicolons, replaces
put(contact, 'tca_budget', l.budget);
put(contact, 'tca_timeline', l.timeline);
put(contact, 'tca_goals', l.goals);
put(contact, 'tca_lead_score', l.score);
put(contact, 'tca_lead_bucket', l.bucket);
put(contact, 'tca_consent', l.consent);
if (!Number.isNaN(receivedMs)) contact.tca_received_at = String(receivedMs);

const who = String(l.company ?? '').trim() || String(l.name ?? '').trim().replace(/\s+/g, ' ') || email;
const what = services.map((s) => SERVICE_LABELS[s] ?? s).join(', ') || 'New enquiry';
const deal = { dealname: (who + ' - ' + what).slice(0, 200), pipeline: PIPELINE_ID };
put(deal, 'tca_lead_id', leadId);
put(deal, 'tca_source', l.source);
put(deal, 'tca_budget', l.budget);
put(deal, 'tca_timeline', l.timeline);
put(deal, 'tca_lead_score', l.score);
put(deal, 'tca_lead_bucket', l.bucket);
// A brief that continues a quiz updates the quiz's deal: leave its stage alone,
// in case someone has already moved it. A new submission starts at "New lead".
if (l.continuesQuiz !== true) deal.dealstage = STAGE_NEW_LEAD;

return [{
  json: {
    email,
    leadId,
    contactBody: { inputs: [{ idProperty: 'email', id: email, properties: contact }] },
    dealBody: { inputs: [{ idProperty: 'tca_lead_id', id: leadId, properties: deal }] },
  },
}];

// One line for the execution log: what was written where.
const c = $('Read lifecycle stage').first().json;
const d = $('Upsert deal').first().json.results?.[0] ?? {};
return [{ json: {
  contactId: c.id,
  dealId: d.id,
  dealStage: d.properties?.dealstage ?? null,
  leadStatusWasEmpty: !c.properties?.hs_lead_status,
  lifecycleStage: c.properties?.lifecyclestage ?? null,
} }];
